def modular_inverse(arr, N, P):
    """Write a function to count array elements having modular inverse under given prime number p equal to itself."""
    if P <= 1:
        return 0
    if N is None:
        limit = len(arr)
    else:
        limit = max(0, int(N))
    count = 0
    for element in arr[:limit]:
        residue = element % P
        if (residue * residue) % P == 1:
            count += 1
    return count
